insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "a62ff29c-3b7e-5207-ae57-1afc64c06c25", "status": "published", "metadata": {"sprint": "15B.5", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §8-9, տպագիր էջեր 27-29", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(2)"}}, "title_hy": "Ինչպե՞ս գնահատել և համեմատել մոլեկուլների չափերը", "hint_1_hy": "Ստուգի՛ր՝ արդյոք բոլոր չափերը տրված են նույն միավորով, և հարցում պահանջվում է դասավորել փոքրից մե՞ծ, թե՞ մեծից փոքր հերթականությամբ։", "hint_2_hy": "Շարքով չափման դեպքում մի՛ օգտագործիր ամբողջ շարքի երկարությունը որպես մեկ մասնիկի չափ. հաշվի՛ր d = L ÷ N  բանաձևով։", "created_at": "2026-10-01T14:50:34.004096+00:00", "updated_at": "2026-10-05T13:34:07.232748+00:00", "strategy_hy": "Նախ բոլոր չափերը արտահայտի՛ր նույն միավորով 1 Å = 10⁻¹⁰ մ։ Համեմատելիս թվերը դասավորի՛ր հարցում պահանջված հերթականությամբ։ Եթե չափում ես կողք կողքի դասավորված միատեսակ փոքր մասնիկների շարք, ապա մեկ մասնիկի չափը որոշելու համար շարքի ընդհանուր երկարությունը բաժանի՛ր մասնիկների թվին՝ d = L ÷ N։", "guide_version": 3, "item_template_id": "ba14a31d-761d-5cdc-9611-951fc4b7a8d3", "worked_example_hy": "Օրինակ՝ եթե 20 միատեսակ գնդիկների շարքի ընդհանուր երկարությունը 40 մմ է, ապա մեկ գնդիկի տրամագիծը 40 մմ ÷ 20 = 2 մմ է։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
